(function() {
  const card = element;
  const textWrapper = card.querySelector('.ScTextWrapper-sc-10mto54-1');
  if (!textWrapper) return;

  const tagsContainer = textWrapper.querySelector('.fsLBGq');
  if (!tagsContainer) return;

  // Move tags container to the top of the text wrapper
  textWrapper.insertBefore(tagsContainer, textWrapper.firstChild);

  // Highlight each tag with a bright background and border
  const tags = tagsContainer.querySelectorAll('.tw-tag');
  tags.forEach(function(tag) {
    tag.style.backgroundColor = '#9147ff';
    tag.style.color = '#ffffff';
    tag.style.borderRadius = '4px';
    tag.style.padding = '2px 8px';
    tag.style.fontWeight = 'bold';
    tag.style.display = 'inline-block';
    tag.style.marginRight = '6px';
    tag.style.marginBottom = '6px';
    tag.style.border = '1px solid #9147ff';
    tag.style.textDecoration = 'none';
  });
})();
